            date: string;
            /** @example 19:00 */
            time: string;
            description?: string;
            photo?: string;
            seats: number;
            /** Format: int64 */
            price_kop?: number;
            /** @default true */
            dogs_allowed: boolean;
            /** @default true */
            signup_enabled: boolean;
            /** @enum {string} */
            status: "draft" | "published";
